// Input validation guardrail.
// Nothing reaches an agent until it has been checked here.
const MAX_LEN = 2000;
const INJECTION_PATTERNS = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions?/i,
  /disregard\s+(the\s+)?(above|previous)/i,
  /system\s+prompt/i,
  /you\s+are\s+now\s+/i,
  /reveal\s+your\s+(instructions?|prompt|rules)/i,
  /forget\s+everything/i
];

const results = [];

for (const item of $input.all()) {
  const b = (item.json && item.json.body) ? item.json.body : (item.json || {});
  const errors = [];

  const businessId  = String(b.business_id || '').trim();
  const channel     = String(b.channel || '').trim().toLowerCase();
  const externalId  = String(b.external_id || '').trim();
  const callerPhone = String(b.caller_phone || '').trim();
  let   message     = String(b.message || '');

  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(businessId)) {
    errors.push('business_id must be a valid UUID');
  }
  if (!['voice', 'whatsapp', 'webchat'].includes(channel)) {
    errors.push('channel must be one of: voice, whatsapp, webchat');
  }
  if (!message.trim()) {
    errors.push('message is required');
  }

  // Cap length rather than reject - a long call transcript is normal,
  // an unbounded one is a cost attack.
  let truncated = false;
  if (message.length > MAX_LEN) {
    message = message.slice(0, MAX_LEN);
    truncated = true;
  }

  // Flag, do not block. The escalation agent decides what to do.
  const injectionFlag = INJECTION_PATTERNS.some(function (re) { return re.test(message); });

  results.push({
    json: {
      valid: errors.length === 0,
      errors: errors,
      business_id: businessId,
      channel: channel,
      external_id: externalId || null,
      caller_phone: callerPhone || null,
      message: message.trim(),
      truncated: truncated,
      injection_flag: injectionFlag
    }
  });
}

return results;

